<section class="admin-v2-page-intro"><div><span class="admin-v2-eyebrow">REFLECTIONS</span><h2>إدارة الخواطر</h2><p>افتح الخاطرة للمراجعة والتحرير الكامل، أو حدّث حالتها مباشرة.</p></div><form class="admin-v2-filter" method="get"><input name="q" value="<?=e($q)?>" placeholder="بحث في الخاطرة أو الكاتب"><select name="status"><option value="">كل الحالات</option><?php foreach(['draft'=>'مسودة','review'=>'مراجعة','changes'=>'تعديلات','rejected'=>'مرفوضة','published'=>'منشورة'] as $k=>$v): ?><option value="<?=e($k)?>" <?=$status===$k?'selected':''?>><?=$v?></option><?php endforeach; ?></select><button class="admin-v2-button primary">تصفية</button></form></section>
<section class="admin-v2-table-panel"><div class="admin-v2-panel-head"><h3>الخواطر</h3><span><?=e(count($rows))?></span></div><div class="admin-v2-responsive-table"><table class="admin-v2-table"><thead><tr><th>الخاطرة</th><th>الكاتب</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="4"><div class="admin-v2-empty">لا توجد خواطر.</div></td></tr><?php else: foreach($rows as $row): ?><tr><td><strong><?=e($row['title']??'خاطرة نصية')?></strong><small><?=e($row['slug']??'')?></small></td><td><?=e($row['author_name']??'')?></td><td><span class="admin-v2-badge <?=e($row['status'])?>"><?=e($row['status'])?></span></td><td class="admin-v2-inline-actions"><a class="admin-v2-button primary" href="/admin/khawatir/<?=e($row['id'])?>">تحرير الخاطرة</a><form method="post" action="/admin-v2/thoughts/action"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($row['id'])?>"><select name="status"><option value="draft">مسودة</option><option value="review">مراجعة</option><option value="changes">تعديلات</option><option value="rejected">مرفوضة</option><option value="published">منشورة</option></select><button class="admin-v2-button" type="submit">حفظ الحالة</button></form></td></tr><?php endforeach; endif; ?></tbody></table></div></section>
